          const newPath = (targetFolder.endsWith('/') ? targetFolder : targetFolder + '/') + folderName;
          if (await adapter.exists(newPath)) { new Notice('目标文件夹已存在'); return false; }
          await adapter.rename(srcPath, newPath);
