          const orderPath = (folder.endsWith('/') ? folder : folder + '/') + '.ifto_order.json';
          if (!await adapter.exists(orderPath)) return [];
          const raw = await adapter.read(orderPath);
          const arr = JSON.parse(raw);
          return Array.isArray(arr) ? arr : [];
